/**
 * Story mention count — a fourth priority signal alongside
 * unppp-priority-count.ts / repo-priority-count.ts / step-priority-count.ts.
 * Scores an unppp by how many stories reference it, per
 * public/data/story-repo-mappings.json (generated by
 * scripts/analyze-story-repo-mentions.js).
 */

export const STORY_MENTION_POINT_VALUE = 5

interface StoryMentionEntry {
  mentionedRepositories: string[]
}

/** The mappings file is keyed by story, each listing which repos it
 *  mentions — invert to a per-unppp mention count. */
export function buildStoryMentionCounts(mappings: Record<string, StoryMentionEntry>): Map<string, number> {
  const counts = new Map<string, number>()
  for (const story of Object.values(mappings)) {
    for (const id of story.mentionedRepositories) {
      counts.set(id, (counts.get(id) ?? 0) + 1)
    }
  }
  return counts
}

export function getStoryMentionPoints(unpppId: string, mentionCounts: Map<string, number>): number {
  return (mentionCounts.get(unpppId) ?? 0) * STORY_MENTION_POINT_VALUE
}
